CREATE    VIEW [EventBrite].[vwAttendee]
AS
SELECT
	CAST(att.[Attendee_Id] AS NVARCHAR(20)) + '_' + CAST(att.[Event_Id] AS NVARCHAR(20)) + '_' + CAST(att.[Organization_Id] AS NVARCHAR(20)) AS [AttendeeKey]
	,CAST(att.[Event_Id] AS NVARCHAR(20)) + '_' + CAST(att.[Organization_Id] AS NVARCHAR(20)) AS [EventKey]
	,CAST(att.[Order_Id] AS NVARCHAR(20)) + '_' + CAST(att.[Event_Id] AS NVARCHAR(20)) + '_' + CAST(att.[Organization_Id] AS NVARCHAR(20)) AS [OrderKey]
	,att.[Attendee_Id]
	,att.[Link_Id]
	,CAST(att.[createdon] AS DATE) AS [Createdon]
	,CAST(att.[modifiedon] AS DATE) AS [Modifiedon]
	,att.[Status] AS [Attendee Status]
	,IIF(att.[IsCanceleld] = 1, 'Yes', 'No') AS [Is Cancelled]
	,IIF(att.[ischeckedin] = 1, 'Yes', 'No') AS [Is Checkedin]
	,att.[Delivery_Method] AS [Delivery Method]
	,att.[Event_Id]
	,att.[Order_Id]
	,att.[Organization_Id]
	,att.[TicketClass_Id]
	,att.[TicketClass_Name] AS [TicketClass Name]
	,att.[Profile_Company] AS [Profile Company]
	,att.[Profile_Email] AS [Profile Email]
	,att.[Profile_FirstName] AS [Profile First Name]
	,att.[Profile_LastName] AS [Profile Last Name]
	,att.[Profile_Gender] AS [Profile Gender]
	,att.[Profile_Age] AS [Profile Age]
	,att.[Profile_Cellphone] AS [Profile Phone]
	,att.[Profile_JobTitle] AS [Profile Job Title]
	,att.[Profile_Name] AS [Profile Name]
	,att.[Profile_Prefix] AS [Profile Prefix]
	,att.[Profile_Suffix] AS [Profile Suffix]
	,IIF(att.[isrefunded] = 1, 'Yes', 'No') AS [Is Refunded]
	,att.[Cost_EventBrite_CurrencyCode] AS [Eventbrite Currency Code]
	,att.[Cost_Base_CurrencyCode] AS [Cost Base Currency Code]
	,att.[Cost_Gross_CurrencyCode] AS [Cost Gross Currency Code]
	,att.[Cost_Payment_CurrencyCode] AS [Cost Payment Currency Code]
	,att.[Cost_Tax_CurrencyCode] AS [Cost Tax Currency Code]
	,att.[Cost_Base_Fee] AS [Cost Base Fee]
	,att.[Cost_EventBrite_Fee] AS [Cost Eventbrite Fee]
	,att.[Cost_Gross_Fee] AS [Cost Gross Fee]
	,att.[Cost_Payment_Fee] AS [Cost Payment Fee]
	,att.[Cost_Tax_Fee] AS [Cost Tax Fee]
	,ev.[Capacity] AS [Event Capacity]
/*	
	,att.[Cost_Base_Fee]/exrBase.ExchangeRate AS [Cost Base Fee GBP]
	,att.[Cost_EventBrite_Fee]/exrEB.[ExchangeRate] AS [Cost Eventbrite Fee GBP]
	,att.[Cost_Gross_Fee]/exrGross.[ExchangeRate] AS [Cost Gross Fee GBP]
	,att.[Cost_Payment_Fee]/exrpayment.[ExchangeRate] AS [Cost Payment Fee GBP]
	,att.[Cost_Tax_Fee]/exrtax.[ExchangeRate] AS [Cost Tax Fee GBP]
*/
	,att.[Cost_Base_Fee]*exrBase.ExchangeRate AS [Cost Base Fee GBP]
	,att.[Cost_EventBrite_Fee]*exrEB.[ExchangeRate] AS [Cost Eventbrite Fee GBP]
	,att.[Cost_Gross_Fee]*exrGross.[ExchangeRate] AS [Cost Gross Fee GBP]
	,att.[Cost_Payment_Fee]*exrpayment.[ExchangeRate] AS [Cost Payment Fee GBP]
	,att.[Cost_Tax_Fee]*exrtax.[ExchangeRate] AS [Cost Tax Fee GBP]

FROM [EventBrite].[tblAttendee] att
	LEFT JOIN [EventBrite].[tblEvent] ev
		ON att.[Event_Id] = ev.[Event_Id]
		AND att.[Organization_Id] = ev.[Organization_Id]
	LEFT JOIN [EventBrite].[vwExchangeRates] exrBase
		ON att.[Cost_Base_CurrencyCode] = exrBase.[CurrencyCode]
	LEFT JOIN [EventBrite].[vwExchangeRates] exrEB
		ON att.[Cost_EventBrite_CurrencyCode] = exrEB.[CurrencyCode]
	LEFT JOIN [EventBrite].[vwExchangeRates] exrGross
		ON att.[Cost_Gross_CurrencyCode] = exrGross.[CurrencyCode]
	LEFT JOIN [EventBrite].[vwExchangeRates] exrpayment
		ON att.[Cost_Payment_CurrencyCode] = exrPayment.[CurrencyCode]
	LEFT JOIN [EventBrite].[vwExchangeRates] exrtax
		ON att.[Cost_Tax_CurrencyCode] = exrtax.[CurrencyCode]
